16	// These tests pin the command-line observable behaviour of saving headers
17	// around ErrHeaderConflict: the queue-level conflict rule is covered directly
18	// in the relayproof package, but users go through stderr rendering and the
19	// exit-code mapping, so a regression there must never show success while the
20	// header was rejected, or report a generic failure that loses the conflict
21	// category. Every scenario runs against a local temp state directory and the
22	// real binary; no chain or external service is involved.
23	
24	// cliPath is the relayproof binary built once for all CLI regression tests.
25	var cliPath string
26	
27	func TestMain(m *testing.M) {
28		dir, err := os.MkdirTemp("", "relayproof-cli-bin-")
29		if err != nil {
30			fmt.Fprintln(os.Stderr, err)
31			os.Exit(1)
32		}
33		cliPath = filepath.Join(dir, "relayproof")
34		// go test runs with the package directory as the working directory.
35		build := exec.Command("go", "build", "-o", cliPath, ".")
36		if out, err := build.CombinedOutput(); err != nil {
37			fmt.Fprintf(os.Stderr, "cannot build relayproof CLI: %v\n%s\n", err, out)
38			os.RemoveAll(dir)
39			os.Exit(1)
40		}
41		code := m.Run()
42		os.Remove(cliPath)
43		os.Remove(dir)
44		os.Exit(code)
45	}
46	
47	type cliResult struct {
48		stdout string
49		stderr string
50		code   int
51	}
52	
53	func runCLI(t *testing.T, args ...string) cliResult {
54		t.Helper()
55		cmd := exec.Command(cliPath, args...)
56		var stdout, stderr bytes.Buffer
57		cmd.Stdout = &stdout
58		cmd.Stderr = &stderr
59		err := cmd.Run()
60		res := cliResult{stdout: stdout.String(), stderr: stderr.String()}
61		if err == nil {
62			return res
63		}
64		var exitErr *exec.ExitError
65		if errors.As(err, &exitErr) {
66			res.code = exitErr.ExitCode()
67			return res
68		}
69		t.Fatalf("run %q: %v", strings.Join(args, " "), err)
70		return cliResult{}
71	}
72	
73	// queueCLI invokes `relayproof queue <sub> --state <state> rest...`. The
74	// per-subcommand flag set parses --state, so it follows the subcommand.
75	func queueCLI(t *testing.T, state, sub string, rest ...string) cliResult {
76		t.Helper()
77		args := append([]string{"queue", sub, "--state", state}, rest...)
78		return runCLI(t, args...)
79	}
