81	func registerSource(t *testing.T, state, chain string) {
82		t.Helper()
83		r := queueCLI(t, state, "register-source", "--chain", chain)
84		if r.code != 0 || r.stdout != "registered source chain "+chain+"\n" {
85			t.Fatalf("register-source %s: code=%d stdout=%q stderr=%q", chain, r.code, r.stdout, r.stderr)
86		}
87	}
