89	func storeHeader(t *testing.T, state, chain string, height int64, root string, trusted bool) cliResult {
90		t.Helper()
91		args := []string{
92			"--chain", chain,
93			"--height", strconv.FormatInt(height, 10),
94			"--root", root,
95		}
96		if trusted {
97			args = append(args, "--trusted")
98		}
99		return queueCLI(t, state, "header", args...)
100	}
101	
102	func wantStoredHeader(chain string, height int64, trusted bool) string {
103		return fmt.Sprintf("stored header chain=%s height=%d trusted=%t\n", chain, height, trusted)
104	}
105	
106	func submitMsg(t *testing.T, state, id, from, to string, nonce uint64, proofAt int64) {
107		t.Helper()
108		r := queueCLI(t, state, "submit",
109			"--id", id, "--from", from, "--to", to,
110			"--nonce", strconv.FormatUint(nonce, 10),
111			"--proof-at", strconv.FormatInt(proofAt, 10),
112			"--payload", "p-"+id,
113			"--expires-at", "9000000000000",
114		)
115		if r.code != 0 {
116			t.Fatalf("submit %s: code=%d stderr=%q", id, r.code, r.stderr)
117		}
118	}
119	
120	type cliResultEntry struct {
121		ID     string `json:"id"`
122		Status string `json:"status"`
123		Reason string `json:"reason"`
124	}
125	
126	type cliAdvanceReport struct {
127		NowMs   int64            `json:"nowMs"`
128		Results []cliResultEntry `json:"results"`
129	}
130	
131	func advanceCLI(t *testing.T, state string, now int64) cliAdvanceReport {
132		t.Helper()
133		r := queueCLI(t, state, "advance", "--now", strconv.FormatInt(now, 10))
134		if r.code != 0 {
135			t.Fatalf("advance at %d: code=%d stderr=%q", now, r.code, r.stderr)
136		}
137		var rep cliAdvanceReport
138		if err := json.Unmarshal([]byte(r.stdout), &rep); err != nil {
139			t.Fatalf("decode advance output %q: %v", r.stdout, err)
140		}
141		return rep
142	}
143	
144	func resultFor(t *testing.T, rep cliAdvanceReport, id string) cliResultEntry {
145		t.Helper()
146		for _, r := range rep.Results {
147			if r.ID == id {
148				return r
149			}
150		}
151		t.Fatalf("advance report has no result for %s: %+v", id, rep.Results)
152		return cliResultEntry{}
153	}
