155	type cliQueryRecord struct {
156		ID        string `json:"id"`
157		Status    string `json:"status"`
158		Reason    string `json:"reason"`
159		Attempts  int    `json:"attempts"`
160		NextRetry int64  `json:"nextRetryMs"`
161	}
162	
163	func queryCLI(t *testing.T, state, id string) cliQueryRecord {
164		t.Helper()
165		r := queueCLI(t, state, "query", "--id", id)
166		if r.code != 0 {
167			t.Fatalf("query %s: code=%d stderr=%q", id, r.code, r.stderr)
168		}
169		var got cliQueryRecord
170		if err := json.Unmarshal([]byte(r.stdout), &got); err != nil {
171			t.Fatalf("decode query output %q: %v", r.stdout, err)
172		}
173		return got
174	}
