201	// With a registered source and an accepted trusted header at height 100 with
202	// root 0xaaa, saving another trusted header at the same height with root
203	// 0xbbb ends with exit code 16 and an explicit conflict error; resaving the
204	// original height and root stays a normal success with the usual output.
205	func TestCLIHeaderConflictExitCode16(t *testing.T) {
206		state := t.TempDir()
207		registerSource(t, state, "chain-a")
208	
209		wantStored := wantStoredHeader("chain-a", 100, true)
210		first := storeHeader(t, state, "chain-a", 100, "0xaaa", true)
211		if first.code != 0 || first.stdout != wantStored {
212			t.Fatalf("initial trusted header: code=%d stdout=%q stderr=%q", first.code, first.stdout, first.stderr)
213		}
214	
215		conflict := storeHeader(t, state, "chain-a", 100, "0xbbb", true)
216		assertHeaderConflict(t, conflict, "chain-a", 100, "0xbbb", "0xaaa")
217	
218		// Same height, original root: idempotent acceptance identical to any
219		// successful header save.
220		again := storeHeader(t, state, "chain-a", 100, "0xaaa", true)
221		if again.code != 0 || again.stdout != wantStored || again.stderr != "" {
222			t.Fatalf("same height/root resave: code=%d stdout=%q stderr=%q", again.code, again.stdout, again.stderr)
223		}
224	}
225	
226	// A conflict must not replace the accepted trusted header nor leave the state
227	// directory unusable: a proof-at-90 message afterwards delivers citing the
228	// trusted height 100, while a proof-at-101 message keeps waiting for a trusted
229	// header.
230	func TestCLIHeaderConflictKeepsCoverageAndQueueUsable(t *testing.T) {
231		state := t.TempDir()
232		registerSource(t, state, "chain-a")
233		if r := storeHeader(t, state, "chain-a", 100, "0xaaa", true); r.code != 0 {
234			t.Fatalf("initial trusted header: %v", r)
235		}
236		assertHeaderConflict(t, storeHeader(t, state, "chain-a", 100, "0xbbb", true),
237			"chain-a", 100, "0xbbb", "0xaaa")
238	
239		// Every CLI invocation opens the directory afresh, so the following
240		// commands also prove the state directory survives a rejected save across
241		// process boundaries.
242		submitMsg(t, state, "m90", "chain-a", "chain-b", 1, 90)
243		rep := advanceCLI(t, state, 1_700_000_000_000)
244		got := resultFor(t, rep, "m90")
245		if got.Status != "success" {
246			t.Fatalf("proof-at-90 must deliver after conflict: %+v", got)
247		}
248		if want := "delivered; proof verified by trusted header at height 100"; got.Reason != want {
249			t.Fatalf("success reason must cite the actually-used trusted height 100: %q", got.Reason)
250		}
251	
252		submitMsg(t, state, "m101", "chain-a", "chain-b", 2, 101)
253		rep = advanceCLI(t, state, 1_700_000_100_000)
254		waiting := resultFor(t, rep, "m101")
255		if want := "waiting for trusted header covering height 101 (current 100)"; waiting.Status != "waiting" || waiting.Reason != want {
256			t.Fatalf("proof-at-101 must still wait on coverage 100: %+v", waiting)
257		}
258		if rec := queryCLI(t, state, "m101"); rec.Attempts != 1 || rec.NextRetry != 1_700_000_101_000 {
259			t.Fatalf("waiting record schedule wrong: %+v", rec)
260		}
261	}
262	
263	// Saving a header never processes messages: after a conflicting (or
264	// idempotent) header save, an already waiting record must keep exactly its
265	// status, reason, attempt count and scheduled retry time.
266	func TestCLIConflictHeaderSaveLeavesWaitingRecordUntouched(t *testing.T) {
267		state := t.TempDir()
268		registerSource(t, state, "chain-a")
269		if r := storeHeader(t, state, "chain-a", 100, "0xaaa", true); r.code != 0 {
270			t.Fatalf("initial trusted header: %v", r)
271		}
272		submitMsg(t, state, "w1", "chain-a", "chain-b", 1, 101)
273		advanceCLI(t, state, 1_700_000_000_000)
274	
275		before := queryCLI(t, state, "w1")
276		wantBefore := cliQueryRecord{
277			ID: "w1", Status: "waiting",
278			Reason:    "waiting for trusted header covering height 101 (current 100)",
279			Attempts:  1,
280			NextRetry: 1_700_000_001_000,
281		}
282		if before != wantBefore {
283			t.Fatalf("setup waiting record wrong: %+v", before)
284		}
285	
286		// Rejected save: exit 16, record untouched.
287		assertHeaderConflict(t, storeHeader(t, state, "chain-a", 100, "0xbbb", true),
288			"chain-a", 100, "0xbbb", "0xaaa")
289		if got := queryCLI(t, state, "w1"); got != before {
290			t.Fatalf("waiting record changed after rejected header save:\nbefore=%+v\nafter =%+v", before, got)
291		}
292	
293		// Accepted same-root save: record still untouched.
294		if r := storeHeader(t, state, "chain-a", 100, "0xaaa", true); r.code != 0 {
295			t.Fatalf("idempotent header save failed: %v", r)
296		}
297		if got := queryCLI(t, state, "w1"); got != before {
298			t.Fatalf("waiting record changed after accepted header save:\nbefore=%+v\nafter =%+v", before, got)
299		}
300	
301		// Advancing before the scheduled retry processes nothing either; the
302		// failed header save must not have moved the processing clock.
303		rep := advanceCLI(t, state, 1_700_000_000_500)
304		if len(rep.Results) != 0 {
305			t.Fatalf("no message is due mid-backoff, got %+v", rep.Results)
306		}
307		if got := queryCLI(t, state, "w1"); got != before {
308			t.Fatalf("waiting record changed on a mid-backoff advance:\nbefore=%+v\nafter =%+v", before, got)
309		}
310	}
311	
312	// Roots compare as the submitted raw strings, byte for byte: surrounding
313	// whitespace and case differences are normal header-root conflicts, not
314	// equivalent roots.
315	func TestCLIHeaderConflictRootsComparedByteForByte(t *testing.T) {
316		state := t.TempDir()
317		registerSource(t, state, "chain-a")
318		if r := storeHeader(t, state, "chain-a", 100, "0xaaa", true); r.code != 0 {
319			t.Fatalf("initial trusted header: %v", r)
320		}
321		for _, root := range []string{"0xAAA", " 0xaaa", "0xaaa ", "0xaaa\t"} {
322			assertHeaderConflict(t, storeHeader(t, state, "chain-a", 100, root, true),
323				"chain-a", 100, root, "0xaaa")
324		}
325		// The original raw string is still accepted byte-for-byte.
326		if r := storeHeader(t, state, "chain-a", 100, "0xaaa", true); r.code != 0 {
327			t.Fatalf("byte-identical root must stay idempotent: code=%d stderr=%q", r.code, r.stderr)
328		}
329	}
330	
331	// Empty roots are legal input: two trusted headers at the same height with
332	// empty roots accept normally, while an empty and a non-empty root conflict in
333	// either submission order with the same conflict category.
334	func TestCLIHeaderConflictEmptyRoots(t *testing.T) {
335		state := t.TempDir()
336		registerSource(t, state, "x")
337	
338		wantStored := wantStoredHeader("x", 1, true)
339		r1 := storeHeader(t, state, "x", 1, "", true)
340		if r1.code != 0 || r1.stdout != wantStored {
341			t.Fatalf("first empty-root trusted header: code=%d stdout=%q stderr=%q", r1.code, r1.stdout, r1.stderr)
342		}
343		r2 := storeHeader(t, state, "x", 1, "", true)
344		if r2.code != 0 || r2.stdout != wantStored {
345			t.Fatalf("second empty-root trusted header must be idempotent: code=%d stdout=%q stderr=%q", r2.code, r2.stdout, r2.stderr)
346		}
347		assertHeaderConflict(t, storeHeader(t, state, "x", 1, "other", true),
348			"x", 1, "other", "")
349	
350		// Reverse direction: accepted non-empty root, submitted empty root.
351		state2 := t.TempDir()
352		registerSource(t, state2, "y")
353		if r := storeHeader(t, state2, "y", 2, "r0", true); r.code != 0 {
354			t.Fatalf("non-empty trusted header: %v", r)
355		}
356		assertHeaderConflict(t, storeHeader(t, state2, "y", 2, "", true),
357			"y", 2, "", "r0")
358	}
359	
360	// An untrusted header at the trusted height with a different root saves
361	// successfully but never replaces the accepted trusted coverage: the accepted
362	// root stays 0xaaa (a later trusted 0xbbb still conflicts), coverage stays at
363	// height 100, and the state directory keeps working.
364	func TestCLIUntrustedSameHeightDifferentRootKeepsCoverage(t *testing.T) {
365		state := t.TempDir()
366		registerSource(t, state, "chain-a")
367		if r := storeHeader(t, state, "chain-a", 100, "0xaaa", true); r.code != 0 {
368			t.Fatalf("initial trusted header: %v", r)
369		}
370	
371		untrusted := storeHeader(t, state, "chain-a", 100, "0xbbb", false)
372		if untrusted.code != 0 || untrusted.stdout != wantStoredHeader("chain-a", 100, false) {
373			t.Fatalf("untrusted same-height header with a different root must save: code=%d stdout=%q stderr=%q",
374				untrusted.code, untrusted.stdout, untrusted.stderr)
375		}
376	
377		// The untrusted write did not become the accepted root: a trusted 0xbbb at
378		// the same height still conflicts against the accepted 0xaaa.
379		assertHeaderConflict(t, storeHeader(t, state, "chain-a", 100, "0xbbb", true),
380			"chain-a", 100, "0xbbb", "0xaaa")
381		if r := storeHeader(t, state, "chain-a", 100, "0xaaa", true); r.code != 0 {
382			t.Fatalf("accepted trusted root must remain idempotent: code=%d stderr=%q", r.code, r.stderr)
383		}
384	
385		// Coverage and normal queue operation are intact.
386		submitMsg(t, state, "m100", "chain-a", "chain-b", 1, 100)
387		rep := advanceCLI(t, state, 1_700_000_000_000)
388		delivered := resultFor(t, rep, "m100")
389		if want := "delivered; proof verified by trusted header at height 100"; delivered.Status != "success" || delivered.Reason != want {
390			t.Fatalf("covered message must deliver via trusted height 100: %+v", delivered)
391		}
392		submitMsg(t, state, "m101", "chain-a", "chain-b", 2, 101)
393		rep = advanceCLI(t, state, 1_700_000_100_000)
394		waiting := resultFor(t, rep, "m101")
395		if waiting.Status != "waiting" || waiting.Reason != "waiting for trusted header covering height 101 (current 100)" {
396			t.Fatalf("untrusted header must not widen trusted coverage: %+v", waiting)
397		}
398	}
