305	// Backoff schedule: 1,2,4,8,16,32,60,60 seconds; jumping across intervals
306	// only consumes one attempt.
307	func TestBackoffScheduleAndJump(t *testing.T) {
308		q, _ := openTempQueue(t)
309		defer q.Close()
310		q.RegisterSource("a")
311		q.Submit(env("m", "a", "b", 1, 10, 0))
312	
313		want := []int64{2000, 4000, 8000, 16000, 32000, 64000, 124000, 184000}
314		now := int64(1000)
315		for attempt, next := range want {
316			q.Advance(now)
317			r := statusOf(t, q, "m")
318			if r.Status != StatusWaiting {
319				t.Fatalf("attempt %d: want waiting, got %s", attempt+1, r.Status)
320			}
321			if r.NextRetry != next {
322				t.Fatalf("attempt %d: want retry %d got %d", attempt+1, next, r.NextRetry)
323			}
324			if r.Attempts != attempt+1 {
