// Validation errors must not touch state.
func TestValidation(t *testing.T) {
	q, _ := openTempQueue(t)
	defer q.Close()
	if _, err := q.Submit(env("", "a", "b", 1, 10, 0)); !errors.Is(err, ErrInvalidArg) {
		t.Fatalf("empty id: %v", err)
	}
